head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용

scwin.vScrenID = "ULDSTF05934.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_gridAddRow = function(pQryId, pBzNm, pCnt) {
    dts_List_1.insertRow();
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "QRY_ID", pQryId);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "BZ_NM", pBzNm);
    dts_List_1.setCellData(dts_List_1.getTotalRow(), "CNT", pCnt);
};
scwin.fn_list_sync = function() {
    //var vBzNm  ="회사신규상장";
    //fn_gridAddRow(vBzNm, fn_count_read_sync('100'));
    dts_List_1.removeAll();
    var gTotalCnt = 0;
    var arrPar = new Array();
    arrPar[0] = {
        BZ_NM: '회사신규상장',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corp.newlist"
    };
    arrPar[1] = {
        BZ_NM: '종목신규상장',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.newlist"
    };
    arrPar[2] = {
        BZ_NM: '회사상장폐지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corp.delist"
    };
    arrPar[3] = {
        BZ_NM: '종목상장폐지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.delist"
    };
    arrPar[4] = {
        BZ_NM: '관리종목지정',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.admisu"
    };
    arrPar[5] = {
        BZ_NM: '매매거래정지',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.haltisu"
    };
    arrPar[6] = {
        BZ_NM: '주식발행',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isu.isslist"
    };
    arrPar[7] = {
        BZ_NM: '상호변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.comnm.change"
    };
    arrPar[8] = {
        BZ_NM: '종목명변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.isunm.change"
    };
    arrPar[9] = {
        BZ_NM: '결산기변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.fiscal.change"
    };
    arrPar[10] = {
        BZ_NM: '업종변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.ind.change"
    };
    arrPar[11] = {
        BZ_NM: '소속부변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.sect.change"
    };
    arrPar[12] = {
        BZ_NM: '대표이사변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.ceo.change"
    };
    arrPar[13] = {
        BZ_NM: '본점소재지변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.addr.change"
    };
    arrPar[14] = {
        BZ_NM: '법인기타정보변경',
        QRY_ID: "lds.stf.lstproc.select.bzproclist.corpetc.change"
    };
    grd_List_1.Redraw = false;
    var gCnt = 0;
    for (var i = 0; i < arrPar.length; i++) {
        gCnt = scwin.fn_count_read_sync(arrPar[i].BZ_NM, arrPar[i].QRY_ID);
        scwin.fn_gridAddRow(arrPar[i].QRY_ID, arrPar[i].BZ_NM, gCnt);
        gTotalCnt += gCnt;
    }
    grd_List_1.Redraw = true;
    $c.stf.FillGridHeaderTotalCnt(gTotalCnt, panel_page_1);

    //dts_List_2 초기화
    dts_List_2.removeAll();
    $c.stf.FillGridHeaderTotalCnt(0, panel_page_2);
};
scwin.fn_getMktTpCd = function() {
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    return vMarketTpCd;
};
scwin.fn_count_read_sync = function(pBzNm, pQryId) {
    dts_Cnt.DataID = encodeURI(scwin.fn_QryUrl(pBzNm, pQryId));
    dts_Cnt.reset();
    return dts_Cnt.getTotalRow();
};


//그리드 더블클릭시 	
scwin.fn_read_sync = function(row, colid) {
    dts_List_2.DataID = encodeURI(scwin.fn_QryUrl(dts_List_1.getCellData(row, 'BZ_NM'), dts_List_1.getCellData(row, 'QRY_ID')));
    dts_List_2.reset();
    $c.cm.ShowWin(grd_List_2);
};
scwin.fn_QryUrl = function(pBzNm, pQryId) {
    var url = "";
    url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=" + pQryId;
    if (pBzNm == '관리종목지정') {
        url += "&outputMessageId=LISTING_BZ_PROCS_LIST_OUT_MAISU";
    } else {
        url += "&outputMessageId=LISTING_BZ_PROCS_LIST_OUT";
    }
    if (pBzNm == '대표이사변경' || pBzNm == '본점소재지변경') {
        url += "&{P}param01=" + $c.stf.getObjectValue(edt_SDate);
        url += "&{P}param02=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param03=" + scwin.fn_getMktTpCd(); // 시장구분

    } else if (pBzNm == '종목명변경' || pBzNm == '관리종목지정') {
        url += "&{P}param01=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param02=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param03=" + $c.stf.getObjectValue(edt_SDate);
        url += "&{P}param04=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param05=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param06=" + $c.stf.getObjectValue(edt_SDate);
    } else {
        url += "&{P}param01=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param02=" + scwin.fn_getMktTpCd(); // 시장구분
        url += "&{P}param03=" + $c.stf.getObjectValue(edt_SDate);
    }
    return url;
};
scwin.fn_gridList2Change = function(pId) {
    if (dts_List_2.getCellData(1, pId) == "") {
        $c.cm.setColumnProp(grd_List_2, pId, "Show", false);
    } else {
        $c.cm.setColumnProp(grd_List_2, pId, "Show", true);
    }
};
scwin.fn_gridList2Init = function() {
    $c.cm.setColumnProp(grd_List_2, "ISUR_CD", "Show", true);
    $c.cm.setColumnProp(grd_List_2, "COM_NM", "Show", true);
    $c.cm.setColumnProp(grd_List_2, "ISU_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "ISU_KOR_NM", "Show", false);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List_1_OnLoadError = function() {
    $c.stf.alert_error(dts_List_1);
};
scwin.dts_List_2_OnLoadError = function() {
    $c.stf.alert_error(dts_List_2);
};
scwin.dts_Cnt_OnLoadError = function() {
    $c.stf.alert_error(dts_Cnt);
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page_2);
    $c.cm.CloseWin(rowcount, grd_List_2);
    if (rowcount > 0) {
        scwin.fn_gridList2Change('ISUR_CD');
        scwin.fn_gridList2Change('COM_NM');
        scwin.fn_gridList2Change('ISU_CD');
        scwin.fn_gridList2Change('ISU_KOR_NM');
    } else {
        scwin.fn_gridList2Init();
    }
};
scwin.grd_List_1_OnClick = function(row, colid) {
    scwin.fn_read_sync(row, colid);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2" || js_market == "6") {
        $c.cm.setColumnProp(grd_List_2, "LD_MKT_TP_NM", "Show", false);
        $c.stf.showObj(panel_mkt_gubun, false);
    } else {
        $c.stf.showObj(panel_mkt_gubun, true);
    }

    //초기화
    $c.cm.setColumnProp(grd_List_2, "ISU_CD", "Show", false);
    $c.cm.setColumnProp(grd_List_2, "ISU_KOR_NM", "Show", false);
    var vHeadString = "QRY_ID:STRING(100),BZ_NM:STRING(300),CNT:STRING(20)";
    //dts_List_1.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    $c.cm.PanelToGroupBox(panel_Top);
    edt_SDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

};
